package com.example.joblinker.activities;

import android.content.Intent;
import android.os.Bundle;
import android.view.Menu;
import android.view.MenuItem;
import android.view.View;
import android.widget.ImageButton;
import android.widget.ImageView;
import android.widget.ProgressBar;
import android.widget.TextView;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;
import androidx.core.widget.NestedScrollView;

import com.example.joblinker.R;
import com.example.joblinker.firebase.JobLinkerFirebaseManager;
import com.example.joblinker.models.Job;
import com.example.joblinker.models.User;
import com.example.joblinker.utils.DateTimeHelper;
import com.example.joblinker.utils.ImageUtils;
import com.example.joblinker.utils.SharedPreferencesManager;
import com.google.android.material.appbar.MaterialToolbar;
import com.google.android.material.button.MaterialButton;
import com.google.android.material.card.MaterialCardView;
import com.google.android.material.chip.Chip;
import com.google.android.material.chip.ChipGroup;

public class JobDetailsActivity extends AppCompatActivity {

    public static final String EXTRA_JOB_ID = "job_id";
    public static final String EXTRA_JOB = "job";

    private MaterialToolbar toolbar;
    private NestedScrollView scrollView;
    private ProgressBar progressBar;

    // Header Views
    private ImageView ivCompanyLogo;
    private TextView tvJobTitle;
    private TextView tvCompanyName;
    private TextView tvLocation;
    private TextView tvSalary;
    private TextView tvPostedTime;
    private Chip chipCategory;
    private Chip chipJobType;
    private ImageButton btnSave;

    // Details Views
    private TextView tvDescription;
    private ChipGroup chipGroupSkills;
    private TextView tvDeadline;
    private TextView tvApplications;
    private TextView tvViews;

    // Employer Info
    private MaterialCardView layoutEmployerInfo; // <-- FIX: was LinearLayout
    private ImageView ivEmployerAvatar;
    private TextView tvEmployerName;
    private TextView tvEmployerEmail;
    private MaterialButton btnContactEmployer;

    // Action Buttons
    private MaterialButton btnApply;
    private MaterialButton btnShare;

    private JobLinkerFirebaseManager firebaseManager;
    private SharedPreferencesManager prefsManager;
    private Job currentJob;
    private String jobId;
    private boolean isSaved = false;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_job_details);

        firebaseManager = JobLinkerFirebaseManager.getInstance();
        prefsManager = SharedPreferencesManager.getInstance(this);

        initializeViews();
        setupToolbar();
        getIntentData();
        setupClickListeners();
        loadJobDetails();
    }

    private void initializeViews() {
        toolbar = findViewById(R.id.toolbar);
        scrollView = findViewById(R.id.scroll_view);
        progressBar = findViewById(R.id.progress_bar);

        // Header
        ivCompanyLogo = findViewById(R.id.iv_company_logo);
        tvJobTitle = findViewById(R.id.tv_job_title);
        tvCompanyName = findViewById(R.id.tv_company_name);
        tvLocation = findViewById(R.id.tv_location);
        tvSalary = findViewById(R.id.tv_salary);
        tvPostedTime = findViewById(R.id.tv_posted_time);
        chipCategory = findViewById(R.id.chip_category);
        chipJobType = findViewById(R.id.chip_job_type);
        btnSave = findViewById(R.id.btn_save);

        // Details
        tvDescription = findViewById(R.id.tv_description);
        chipGroupSkills = findViewById(R.id.chip_group_skills);
        tvDeadline = findViewById(R.id.tv_deadline);
        tvApplications = findViewById(R.id.tv_applications);
        tvViews = findViewById(R.id.tv_views);

        // Employer Info
        layoutEmployerInfo = findViewById(R.id.layout_employer_info);
        ivEmployerAvatar = findViewById(R.id.iv_employer_avatar);
        tvEmployerName = findViewById(R.id.tv_employer_name);
        tvEmployerEmail = findViewById(R.id.tv_employer_email);
        btnContactEmployer = findViewById(R.id.btn_contact_employer);

        // Action Buttons
        btnApply = findViewById(R.id.btn_apply);
        btnShare = findViewById(R.id.btn_share);
    }

    private void setupToolbar() {
        setSupportActionBar(toolbar);
        toolbar.setNavigationOnClickListener(v -> onBackPressed());
    }

    private void getIntentData() {
        Intent intent = getIntent();

        // Try to get job object first
        if (intent.hasExtra(EXTRA_JOB)) {
            currentJob = (Job) intent.getSerializableExtra(EXTRA_JOB);
            if (currentJob != null) {
                jobId = currentJob.getJobId();
            }
        }

        // Fall back to job ID
        if (jobId == null && intent.hasExtra(EXTRA_JOB_ID)) {
            jobId = intent.getStringExtra(EXTRA_JOB_ID);
        }
    }

    private void setupClickListeners() {
        btnSave.setOnClickListener(v -> toggleSaveJob());
        btnApply.setOnClickListener(v -> applyForJob());
        btnShare.setOnClickListener(v -> shareJob());
        btnContactEmployer.setOnClickListener(v -> contactEmployer());
    }

    private void loadJobDetails() {
        if (currentJob != null) {
            displayJobDetails(currentJob);
            incrementViewCount();
            checkIfSaved();
        } else if (jobId != null) {
            showLoading(true);
            firebaseManager.getJob(jobId, new JobLinkerFirebaseManager.DataCallback<Job>() {
                @Override
                public void onSuccess(Job job) {
                    showLoading(false);
                    currentJob = job;
                    displayJobDetails(job);
                    incrementViewCount();
                    checkIfSaved();
                }

                @Override
                public void onFailure(String error) {
                    showLoading(false);
                    Toast.makeText(JobDetailsActivity.this,
                            "Error loading job: " + error, Toast.LENGTH_SHORT).show();
                    finish();
                }
            });
        } else {
            Toast.makeText(this, "Invalid job", Toast.LENGTH_SHORT).show();
            finish();
        }
    }

    private void displayJobDetails(Job job) {
        // Header
        ImageUtils.loadCompanyLogo(this, job.getCompanyLogoUrl(), ivCompanyLogo);
        tvJobTitle.setText(job.getJobTitle());
        tvCompanyName.setText(job.getJobCompany());
        tvLocation.setText(job.getLocation());
        tvSalary.setText(job.getSalaryRange());
        tvPostedTime.setText(DateTimeHelper.getRelativeTime(job.getCreatedAt()));
        chipCategory.setText(job.getJobCategory());
        chipJobType.setText(job.getJobType());

        // Description
        tvDescription.setText(job.getJobDescription());

        // Skills
        if (job.getJobSkills() != null && !job.getJobSkills().isEmpty()) {
            chipGroupSkills.setVisibility(View.VISIBLE);
            chipGroupSkills.removeAllViews();
            for (String skill : job.getJobSkills()) {
                Chip chip = new Chip(this);
                chip.setText(skill);
                chip.setClickable(false);
                chip.setChipBackgroundColorResource(R.color.surface_dark);
                chipGroupSkills.addView(chip);
            }
        } else {
            chipGroupSkills.setVisibility(View.GONE);
        }

        // Deadline
        if (job.getDeadline() > 0) {
            tvDeadline.setText(DateTimeHelper.formatDate(job.getDeadline()));
            tvDeadline.setVisibility(View.VISIBLE);
        } else {
            tvDeadline.setVisibility(View.GONE);
        }

        // Statistics
        tvApplications.setText(String.valueOf(job.getApplicantCount()));
        tvViews.setText(String.valueOf(job.getViewCount()));

        // Load employer info
        loadEmployerInfo(job.getJobEmployerId());

        // Apply button logic:
        // - Hide for employers
        // - Show "Already Applied" if user already applied
        // - Show "Job Expired" if deadline passed
        if (prefsManager.isEmployer()) {
            btnApply.setVisibility(View.GONE);
        } else if (job.isDeadlinePassed()) {
            btnApply.setText(R.string.job_expired);
            btnApply.setEnabled(false);
        } else {
            String currentUserId = firebaseManager.getCurrentUserId();
            if (currentUserId != null && job.hasUserApplied(currentUserId)) {
                btnApply.setText(R.string.already_applied);
                btnApply.setEnabled(false);
            } else {
                btnApply.setText(R.string.apply_now);
                btnApply.setEnabled(true);
            }
        }
    }

    private void loadEmployerInfo(String employerId) {
        firebaseManager.getUser(employerId, new JobLinkerFirebaseManager.DataCallback<User>() {
            @Override
            public void onSuccess(User employer) {
                layoutEmployerInfo.setVisibility(View.VISIBLE);
                ImageUtils.loadCircularImage(JobDetailsActivity.this,
                        employer.getAvatarUrl(), ivEmployerAvatar);
                tvEmployerName.setText(employer.getUserName());
                tvEmployerEmail.setText(employer.getUserEmail());
            }

            @Override
            public void onFailure(String error) {
                layoutEmployerInfo.setVisibility(View.GONE);
            }
        });
    }

    private void incrementViewCount() {
        if (jobId != null) {
            firebaseManager.incrementJobViewCount(jobId);
        }
    }

    private void checkIfSaved() {
        String userId = firebaseManager.getCurrentUserId();
        if (userId != null && jobId != null) {
            firebaseManager.hasUserSavedJob(userId, jobId,
                    new JobLinkerFirebaseManager.DataCallback<Boolean>() {
                        @Override
                        public void onSuccess(Boolean saved) {
                            isSaved = saved;
                            updateSaveButton();
                        }

                        @Override
                        public void onFailure(String error) {
                            // Ignore error
                        }
                    });
        }
    }

    private void toggleSaveJob() {
        String userId = firebaseManager.getCurrentUserId();
        if (userId == null || jobId == null) {
            Toast.makeText(this, "Please login to save jobs", Toast.LENGTH_SHORT).show();
            return;
        }

        btnSave.setEnabled(false);

        if (isSaved) {
            // Unsave
            firebaseManager.unsaveJob(userId, jobId, new JobLinkerFirebaseManager.VoidCallback() {
                @Override
                public void onSuccess() {
                    isSaved = false;
                    updateSaveButton();
                    btnSave.setEnabled(true);
                    Toast.makeText(JobDetailsActivity.this,
                            "Job removed from saved", Toast.LENGTH_SHORT).show();
                }

                @Override
                public void onFailure(String error) {
                    btnSave.setEnabled(true);
                    Toast.makeText(JobDetailsActivity.this,
                            "Error: " + error, Toast.LENGTH_SHORT).show();
                }
            });
        } else {
            // Save
            firebaseManager.saveJob(userId, jobId, new JobLinkerFirebaseManager.VoidCallback() {
                @Override
                public void onSuccess() {
                    isSaved = true;
                    updateSaveButton();
                    btnSave.setEnabled(true);
                    Toast.makeText(JobDetailsActivity.this,
                            "Job saved successfully", Toast.LENGTH_SHORT).show();
                }

                @Override
                public void onFailure(String error) {
                    btnSave.setEnabled(true);
                    Toast.makeText(JobDetailsActivity.this,
                            "Error: " + error, Toast.LENGTH_SHORT).show();
                }
            });
        }
    }

    private void updateSaveButton() {
        if (isSaved) {
            btnSave.setImageResource(R.drawable.ic_bookmark);
        } else {
            btnSave.setImageResource(R.drawable.ic_bookmark_border);
        }
    }

    private void applyForJob() {
        if (currentJob == null) return;

        String userId = firebaseManager.getCurrentUserId();
        if (userId == null) {
            Toast.makeText(this, "Please login to apply", Toast.LENGTH_SHORT).show();
            return;
        }

        // ── Cover letter dialog ───────────────────
        android.widget.EditText etCoverLetter = new android.widget.EditText(this);
        etCoverLetter.setHint("Write a short cover letter (optional)…");
        etCoverLetter.setInputType(android.text.InputType.TYPE_CLASS_TEXT
            | android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);
        etCoverLetter.setMinLines(4);
        etCoverLetter.setMaxLines(8);
        etCoverLetter.setGravity(android.view.Gravity.TOP | android.view.Gravity.START);
        etCoverLetter.setBackground(getResources().getDrawable(R.drawable.bg_rounded_white, null));
        int pad = (int)(16 * getResources().getDisplayMetrics().density);
        etCoverLetter.setPadding(pad, pad, pad, pad);

        android.widget.LinearLayout layout = new android.widget.LinearLayout(this);
        layout.setOrientation(android.widget.LinearLayout.VERTICAL);
        layout.setPadding(pad, pad / 2, pad, 0);

        android.widget.TextView tvHint = new android.widget.TextView(this);
        tvHint.setText("Applying for: " + currentJob.getJobTitle()
            + " at " + currentJob.getJobCompany());
        tvHint.setTextSize(14f);
        tvHint.setTextColor(getResources().getColor(R.color.text_secondary, null));
        tvHint.setPadding(0, 0, 0, pad / 2);
        layout.addView(tvHint);
        layout.addView(etCoverLetter);

        new androidx.appcompat.app.AlertDialog.Builder(this)
            .setTitle("Apply for this job")
            .setView(layout)
            .setPositiveButton("Submit Application", (dialog, which) -> {
                String coverLetter = etCoverLetter.getText().toString().trim();
                submitApplication(coverLetter);
            })
            .setNegativeButton("Cancel", null)
            .show();
    }

    private void submitApplication(String coverLetter) {
        String userId = firebaseManager.getCurrentUserId();
        if (userId == null || currentJob == null) return;

        btnApply.setEnabled(false);
        btnApply.setText(R.string.applying);

        // Save full application object
        com.example.joblinker.models.Application application =
            new com.example.joblinker.models.Application(
                null, jobId, userId,
                currentJob.getJobEmployerId(), coverLetter);
        application.setJobTitle(currentJob.getJobTitle());

        firebaseManager.submitApplication(application,
            new JobLinkerFirebaseManager.VoidCallback() {
                @Override
                public void onSuccess() {
                    // Also mark job as applied
                    firebaseManager.addJobApplicant(jobId, userId,
                        new JobLinkerFirebaseManager.VoidCallback() {
                            @Override public void onSuccess() {}
                            @Override public void onFailure(String e) {}
                        });
                    btnApply.setText(R.string.already_applied);
                    btnApply.setEnabled(false);
                    Toast.makeText(JobDetailsActivity.this,
                        "✅ Application submitted!", Toast.LENGTH_SHORT).show();
                }

                @Override
                public void onFailure(String error) {
                    btnApply.setEnabled(true);
                    btnApply.setText(R.string.apply_now);
                    Toast.makeText(JobDetailsActivity.this,
                        "Error: " + error, Toast.LENGTH_SHORT).show();
                }
            });
    }

    private void shareJob() {
        if (currentJob == null) return;

        String shareText = String.format(
                "Check out this job opportunity!\n\n" +
                        "%s at %s\n\n" +
                        "Location: %s\n" +
                        "Salary: %s\n\n" +
                        "Shared via JobLinker",
                currentJob.getJobTitle(),
                currentJob.getJobCompany(),
                currentJob.getLocation(),
                currentJob.getSalaryRange()
        );

        Intent shareIntent = new Intent(Intent.ACTION_SEND);
        shareIntent.setType("text/plain");
        shareIntent.putExtra(Intent.EXTRA_SUBJECT, currentJob.getJobTitle());
        shareIntent.putExtra(Intent.EXTRA_TEXT, shareText);
        startActivity(Intent.createChooser(shareIntent, "Share job via"));
    }

    private void contactEmployer() {
        if (currentJob == null || jobId == null) {
            Toast.makeText(this, "Job info not available", Toast.LENGTH_SHORT).show();
            return;
        }

        // Read the raw Firestore document — most reliable way to get employer ID
        // regardless of which field name was used when the job was posted
        btnContactEmployer.setEnabled(false);
        com.google.firebase.firestore.FirebaseFirestore.getInstance()
            .collection("jobs")
            .document(jobId)
            .get()
            .addOnSuccessListener(doc -> {
                btnContactEmployer.setEnabled(true);
                if (!doc.exists()) {
                    Toast.makeText(this, "Job not found", Toast.LENGTH_SHORT).show();
                    return;
                }

                // Try every possible field name for employer ID
                String employerId = null;
                for (String field : new String[]{"jobEmployerId","employerId","employer_id","ownerId","userId"}) {
                    String val = doc.getString(field);
                    if (val != null && !val.isEmpty()) {
                        employerId = val;
                        break;
                    }
                }

                if (employerId == null || employerId.isEmpty()) {
                    Toast.makeText(this,
                        "Employer contact not available for this job",
                        Toast.LENGTH_SHORT).show();
                    return;
                }

                // Get employer name — use already-loaded name or job company as fallback
                String employerName = (tvEmployerName != null
                        && tvEmployerName.getText().length() > 0)
                    ? tvEmployerName.getText().toString()
                    : currentJob.getJobCompany();

                openChat(employerId,
                    (employerName != null && !employerName.isEmpty()) ? employerName : "Employer");
            })
            .addOnFailureListener(e -> {
                btnContactEmployer.setEnabled(true);
                Toast.makeText(this, "Error: " + e.getMessage(), Toast.LENGTH_SHORT).show();
            });
    }

    private void openChat(String employerId, String employerName) {
        Intent intent = new Intent(JobDetailsActivity.this, ChatActivity.class);
        intent.putExtra(ChatActivity.EXTRA_USER_ID,   employerId);
        intent.putExtra(ChatActivity.EXTRA_USER_NAME, employerName);
        startActivity(intent);
    }

    private void showReportDialog() {
        String[] reasons = {
            "Fake or scam job",
            "Inappropriate content",
            "Duplicate listing",
            "Wrong category",
            "Misleading information",
            "Other"
        };

        final int[] selectedReason = {0};

        new androidx.appcompat.app.AlertDialog.Builder(this)
            .setTitle("Report this job")
            .setSingleChoiceItems(reasons, 0, (dialog, which) -> selectedReason[0] = which)
            .setPositiveButton("Submit Report", (dialog, which) -> {
                String reason = reasons[selectedReason[0]];
                submitReport(reason);
            })
            .setNegativeButton("Cancel", null)
            .show();
    }

    private void submitReport(String reason) {
        if (currentJob == null) return;

        // Save report to Firestore
        java.util.Map<String, Object> report = new java.util.HashMap<>();
        report.put("jobId",       currentJob.getJobId());
        report.put("jobTitle",    currentJob.getJobTitle());
        report.put("reason",      reason);
        report.put("reportedBy",  com.google.firebase.auth.FirebaseAuth.getInstance().getUid());
        report.put("reportedAt",  System.currentTimeMillis());

        com.google.firebase.firestore.FirebaseFirestore.getInstance()
            .collection("reports")
            .add(report)
            .addOnSuccessListener(ref ->
                Toast.makeText(this, "Report submitted. Thank you!", Toast.LENGTH_SHORT).show())
            .addOnFailureListener(e ->
                Toast.makeText(this, "Failed to submit report", Toast.LENGTH_SHORT).show());
    }

    private void showLoading(boolean show) {
        progressBar.setVisibility(show ? View.VISIBLE : View.GONE);
        scrollView.setVisibility(show ? View.GONE : View.VISIBLE);
    }

    @Override
    public boolean onCreateOptionsMenu(Menu menu) {
        getMenuInflater().inflate(R.menu.menu_job_details, menu);
        return true;
    }

    @Override
    public boolean onOptionsItemSelected(MenuItem item) {
        int id = item.getItemId();

        if (id == R.id.action_share) {
            shareJob();
            return true;
        } else if (id == R.id.action_report) {
            showReportDialog();
            return true;
        }

        return super.onOptionsItemSelected(item);
    }
}

ChatActivity:
package com.example.joblinker.activities;

import android.Manifest;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.media.MediaPlayer;
import android.media.MediaRecorder;
import android.net.Uri;
import android.os.Build;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.provider.MediaStore;
import android.text.Editable;
import android.text.TextWatcher;
import android.util.Log;
import android.view.View;
import android.widget.ImageButton;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.TextView;
import android.widget.Toast;

import androidx.activity.result.ActivityResultLauncher;
import androidx.activity.result.contract.ActivityResultContracts;
import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.app.ActivityCompat;
import androidx.core.content.ContextCompat;
import androidx.core.content.FileProvider;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.example.joblinker.R;
import com.example.joblinker.adapters.MessageAdapter;
import com.example.joblinker.firebase.JobLinkerFirebaseManager;
import com.example.joblinker.models.Message;
import com.example.joblinker.models.User;
import com.example.joblinker.utils.ImageUtils;
import com.google.android.material.appbar.MaterialToolbar;
import com.google.android.material.floatingactionbutton.FloatingActionButton;
import com.google.android.material.textfield.TextInputEditText;
import com.google.firebase.firestore.ListenerRegistration;

import java.io.File;
import java.io.IOException;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;
import java.util.Locale;

public class ChatActivity extends AppCompatActivity {

    public static final String EXTRA_USER_ID         = "user_id";
    public static final String EXTRA_USER_NAME       = "user_name";
    public static final String EXTRA_USER_AVATAR     = "user_avatar";
    public static final String EXTRA_CONVERSATION_ID = "conversation_id";

    private static final int REQUEST_RECORD_AUDIO = 201;
    private static final int REQUEST_CAMERA       = 202;

    private MaterialToolbar toolbar;
    private ImageView ivUserAvatar;
    private TextView tvUserName, tvStatus, tvTyping, tvRecordingTime;
    private ImageButton btnVoiceCall, btnVideoCall, btnAttachment, btnEmoji,
            btnCamera, btnCancelRecording;
    private LinearLayout layoutAttachmentTray, layoutRecordingBar;
    private LinearLayout trayCamera, trayGallery, trayDocument, trayLocation, trayContact;
    private View viewRecordingDot;
    private RecyclerView recyclerMessages;
    private TextInputEditText etMessage;
    private FloatingActionButton btnSend;

    private MessageAdapter messageAdapter;
    private final List<Message> messages = new ArrayList<>();
    private JobLinkerFirebaseManager firebaseManager;

    // ── Audio playback ────────────────────────────
    private MediaPlayer audioPlayer = null;
    private String      playingUrl  = null;

    // ── Audio focus ───────────────────────────────
    private android.media.AudioManager      audioManager;
    private android.media.AudioFocusRequest audioFocusRequest;

    private ListenerRegistration messageListener;
    private String otherUserId, otherUserName, otherUserAvatar, conversationId, currentUserId;

    // ── Voice recording ───────────────────────────
    private MediaRecorder mediaRecorder;
    private String audioFilePath;
    private boolean isRecording = false;
    private final Handler recordingHandler = new Handler(Looper.getMainLooper());
    private Runnable recordingTimerRunnable;
    private int recordingSeconds = 0;

    private Uri cameraImageUri;

    private final ActivityResultLauncher<Intent> galleryLauncher =
            registerForActivityResult(new ActivityResultContracts.StartActivityForResult(), result -> {
                if (result.getResultCode() == RESULT_OK && result.getData() != null) {
                    Uri uri = result.getData().getData();
                    if (uri != null) sendImageMessage(uri);
                }
            });

    private final ActivityResultLauncher<Intent> cameraLauncher =
            registerForActivityResult(new ActivityResultContracts.StartActivityForResult(), result -> {
                if (result.getResultCode() == RESULT_OK && cameraImageUri != null)
                    sendImageMessage(cameraImageUri);
            });

    private final ActivityResultLauncher<Intent> documentLauncher =
            registerForActivityResult(new ActivityResultContracts.StartActivityForResult(), result -> {
                if (result.getResultCode() == RESULT_OK && result.getData() != null) {
                    Uri uri = result.getData().getData();
                    if (uri != null) sendDocumentMessage(uri);
                }
            });

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.chat);

        firebaseManager = JobLinkerFirebaseManager.getInstance();
        currentUserId   = firebaseManager.getCurrentUserId();

        getIntentData();
        if (isFinishing()) return;

        initializeViews();
        setupToolbar();
        setupRecyclerView();
        setupClickListeners();
        setupMessageListener();
        loadUserStatus();
    }

    private void getIntentData() {
        Intent i        = getIntent();
        otherUserId     = i.getStringExtra(EXTRA_USER_ID);
        otherUserName   = i.getStringExtra(EXTRA_USER_NAME);
        otherUserAvatar = i.getStringExtra(EXTRA_USER_AVATAR);
        conversationId  = i.getStringExtra(EXTRA_CONVERSATION_ID);

        if (otherUserId == null || otherUserId.isEmpty()) {
            Toast.makeText(this, "Could not open chat — employer info missing",
                    Toast.LENGTH_SHORT).show();
            finish();
            return;
        }
        if (conversationId == null)
            conversationId = JobLinkerFirebaseManager.generateConversationId(currentUserId, otherUserId);
    }

    private void initializeViews() {
        toolbar              = findViewById(R.id.toolbar);
        ivUserAvatar         = findViewById(R.id.iv_user_avatar);
        tvUserName           = findViewById(R.id.tv_user_name);
        tvStatus             = findViewById(R.id.tv_status);
        tvTyping             = findViewById(R.id.tv_typing);
        btnVoiceCall         = findViewById(R.id.btn_voice_call);
        btnVideoCall         = findViewById(R.id.btn_video_call);
        btnAttachment        = findViewById(R.id.btn_attachment);
        btnEmoji             = findViewById(R.id.btn_emoji);
        btnCamera            = findViewById(R.id.btn_camera);
        btnCancelRecording   = findViewById(R.id.btn_cancel_recording);
        layoutAttachmentTray = findViewById(R.id.layout_attachment_tray);
        layoutRecordingBar   = findViewById(R.id.layout_recording_bar);
        viewRecordingDot     = findViewById(R.id.view_recording_dot);
        tvRecordingTime      = findViewById(R.id.tv_recording_time);
        trayCamera           = findViewById(R.id.tray_camera);
        trayGallery          = findViewById(R.id.tray_gallery);
        trayDocument         = findViewById(R.id.tray_document);
        trayLocation         = findViewById(R.id.tray_location);
        trayContact          = findViewById(R.id.tray_contact);
        recyclerMessages     = findViewById(R.id.recycler_messages);
        etMessage            = findViewById(R.id.et_message);
        btnSend              = findViewById(R.id.btn_send);

        tvUserName.setText(otherUserName);
        ImageUtils.loadCircularImage(this, otherUserAvatar, ivUserAvatar);
    }

    private void setupToolbar() {
        setSupportActionBar(toolbar);
        toolbar.setNavigationOnClickListener(v -> onBackPressed());
    }

    private void setupRecyclerView() {
        messageAdapter = new MessageAdapter(this, messages, currentUserId);
        LinearLayoutManager lm = new LinearLayoutManager(this);
        lm.setStackFromEnd(true);
        recyclerMessages.setLayoutManager(lm);
        recyclerMessages.setAdapter(messageAdapter);
    }

    private void setupClickListeners() {
        btnVoiceCall.setOnClickListener(v -> initiateCall("voice"));
        btnVideoCall.setOnClickListener(v -> initiateCall("video"));

        btnEmoji.setOnClickListener(v -> {
            etMessage.requestFocus();
            if (etMessage.isShown()) {
                etMessage.setInputType(
                        android.text.InputType.TYPE_CLASS_TEXT |
                                android.text.InputType.TYPE_TEXT_VARIATION_NORMAL);
            }
            android.view.inputmethod.InputMethodManager imm =
                    (android.view.inputmethod.InputMethodManager) getSystemService(INPUT_METHOD_SERVICE);
            if (imm != null) imm.showSoftInput(etMessage, 0);
        });

        btnCamera.setOnClickListener(v -> openCamera());
        btnAttachment.setOnClickListener(v -> toggleAttachmentTray());

        trayCamera.setOnClickListener(v   -> { closeTray(); openCamera();    });
        trayGallery.setOnClickListener(v  -> { closeTray(); openGallery();   });
        trayDocument.setOnClickListener(v -> { closeTray(); openDocument();  });
        trayLocation.setOnClickListener(v -> { closeTray(); shareLocation(); });
        trayContact.setOnClickListener(v  -> { closeTray(); shareContact();  });

        btnCancelRecording.setOnClickListener(v -> cancelRecording());

        btnSend.setOnClickListener(v -> {
            if (isRecording) { stopRecordingAndSend(); return; }
            String text = etMessage.getText() != null ? etMessage.getText().toString().trim() : "";
            if (!text.isEmpty()) sendTextMessage(text);
            else                 startVoiceRecording();
        });

        btnSend.setOnLongClickListener(v -> { startVoiceRecording(); return true; });

        etMessage.addTextChangedListener(new TextWatcher() {
            @Override public void beforeTextChanged(CharSequence s, int i, int i1, int i2) {}
            @Override public void afterTextChanged(Editable s) {}
            @Override
            public void onTextChanged(CharSequence s, int start, int before, int count) {
                btnSend.setImageResource(s.length() > 0 ? R.drawable.ic_send : R.drawable.ic_mic);
            }
        });
    }

    private void toggleAttachmentTray() {
        if (layoutAttachmentTray.getVisibility() == View.VISIBLE) closeTray();
        else {
            layoutAttachmentTray.setVisibility(View.VISIBLE);
            btnAttachment.setImageResource(R.drawable.ic_close);
        }
    }

    private void closeTray() {
        layoutAttachmentTray.setVisibility(View.GONE);
        btnAttachment.setImageResource(R.drawable.ic_attachment);
    }

    private void openCamera() {
        if (ContextCompat.checkSelfPermission(this, Manifest.permission.CAMERA)
                != PackageManager.PERMISSION_GRANTED) {
            ActivityCompat.requestPermissions(this,
                    new String[]{Manifest.permission.CAMERA}, REQUEST_CAMERA);
            return;
        }
        try {
            File photoFile = createTempImageFile();
            cameraImageUri = FileProvider.getUriForFile(this,
                    getPackageName() + ".fileprovider", photoFile);
            Intent intent = new Intent(MediaStore.ACTION_IMAGE_CAPTURE);
            intent.putExtra(MediaStore.EXTRA_OUTPUT, cameraImageUri);
            cameraLauncher.launch(intent);
        } catch (IOException e) {
            Toast.makeText(this, "Could not open camera", Toast.LENGTH_SHORT).show();
        }
    }

    private File createTempImageFile() throws IOException {
        String timeStamp = new SimpleDateFormat("yyyyMMdd_HHmmss", Locale.getDefault()).format(new Date());
        File storageDir  = getExternalFilesDir(android.os.Environment.DIRECTORY_PICTURES);
        return File.createTempFile("IMG_" + timeStamp, ".jpg", storageDir);
    }

    private void openGallery() {
        Intent intent;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU)
            intent = new Intent(MediaStore.ACTION_PICK_IMAGES);
        else
            intent = new Intent(Intent.ACTION_PICK, MediaStore.Images.Media.EXTERNAL_CONTENT_URI);
        galleryLauncher.launch(intent);
    }

    private void openDocument() {
        Intent intent = new Intent(Intent.ACTION_GET_CONTENT);
        intent.setType("*/*");
        intent.addCategory(Intent.CATEGORY_OPENABLE);
        documentLauncher.launch(Intent.createChooser(intent, "Select Document"));
    }

    private void shareLocation() {
        android.location.LocationManager lm =
                (android.location.LocationManager) getSystemService(LOCATION_SERVICE);
        try {
            android.location.Location loc = null;
            if (ContextCompat.checkSelfPermission(this,
                    Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED) {
                loc = lm.getLastKnownLocation(android.location.LocationManager.GPS_PROVIDER);
                if (loc == null)
                    loc = lm.getLastKnownLocation(android.location.LocationManager.NETWORK_PROVIDER);
            }
            if (loc != null) {
                String mapsUrl = "https://maps.google.com/?q=" + loc.getLatitude() + "," + loc.getLongitude();
                Message msg = new Message(conversationId, currentUserId, otherUserId,
                        "📍 Location: " + mapsUrl);
                msg.setMessageType("location");
                sendMessageObject(msg);
            } else {
                Toast.makeText(this, "Could not get location. Enable GPS and try again.",
                        Toast.LENGTH_SHORT).show();
            }
        } catch (SecurityException e) {
            ActivityCompat.requestPermissions(this,
                    new String[]{Manifest.permission.ACCESS_FINE_LOCATION}, 203);
        }
    }

    private void shareContact() {
        Intent intent = new Intent(Intent.ACTION_PICK,
                android.provider.ContactsContract.Contacts.CONTENT_URI);
        startActivityForResult(intent, 204);
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (requestCode == 204 && resultCode == RESULT_OK && data != null) {
            Uri contactUri = data.getData();
            if (contactUri != null) {
                android.database.Cursor cursor = getContentResolver().query(
                        contactUri, null, null, null, null);
                if (cursor != null && cursor.moveToFirst()) {
                    int nameIdx = cursor.getColumnIndex(
                            android.provider.ContactsContract.Contacts.DISPLAY_NAME);
                    String name = nameIdx >= 0 ? cursor.getString(nameIdx) : "Contact";
                    cursor.close();
                    Message msg = new Message(conversationId, currentUserId, otherUserId,
                            "👤 Contact: " + name);
                    msg.setMessageType("contact");
                    sendMessageObject(msg);
                }
            }
        }
    }

    // ══════════════════════════════════════════════
    // VOICE RECORDING
    // ══════════════════════════════════════════════
    private void startVoiceRecording() {
        if (ContextCompat.checkSelfPermission(this, Manifest.permission.RECORD_AUDIO)
                != PackageManager.PERMISSION_GRANTED) {
            ActivityCompat.requestPermissions(this,
                    new String[]{Manifest.permission.RECORD_AUDIO}, REQUEST_RECORD_AUDIO);
            return;
        }

        isRecording = true;
        recordingSeconds = 0;
        layoutRecordingBar.setVisibility(View.VISIBLE);
        btnSend.setImageResource(R.drawable.ic_stop);
        tvRecordingTime.setText("0:00");

        recordingTimerRunnable = new Runnable() {
            @Override public void run() {
                if (!isRecording) return;
                recordingSeconds++;
                int m = recordingSeconds / 60, s = recordingSeconds % 60;
                tvRecordingTime.setText(String.format(Locale.getDefault(), "%d:%02d", m, s));
                recordingHandler.postDelayed(this, 1000);
            }
        };
        recordingHandler.postDelayed(recordingTimerRunnable, 1000);
        startRecordingDotAnimation();

        audioFilePath = getExternalCacheDir().getAbsolutePath()
                + "/voice_" + System.currentTimeMillis() + ".3gp";
        final String filePath = audioFilePath;

        new Thread(() -> {
            try {
                MediaRecorder recorder = new MediaRecorder();
                recorder.setAudioSource(MediaRecorder.AudioSource.MIC);
                recorder.setOutputFormat(MediaRecorder.OutputFormat.THREE_GPP);
                recorder.setOutputFile(filePath);
                recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AMR_NB);
                recorder.prepare();
                recorder.start();
                // ✅ FIX: check isRecording in case user cancelled before runOnUiThread fired
                runOnUiThread(() -> {
                    if (!isRecording) {
                        try { recorder.stop(); } catch (Exception ignored) {}
                        recorder.release();
                        new File(filePath).delete();
                    } else {
                        mediaRecorder = recorder;
                    }
                });
            } catch (Exception e) {
                runOnUiThread(() -> {
                    isRecording = false;
                    recordingHandler.removeCallbacks(recordingTimerRunnable);
                    layoutRecordingBar.setVisibility(View.GONE);
                    btnSend.setImageResource(R.drawable.ic_mic);
                    Toast.makeText(this, "Failed to start recording: " + e.getMessage(),
                            Toast.LENGTH_SHORT).show();
                });
            }
        }).start();
    }

    private void stopRecordingAndSend() {
        if (!isRecording) return;
        stopRecording();

        String duration = tvRecordingTime != null ? tvRecordingTime.getText().toString() : "0:00";
        try {
            java.io.File audioFile = new java.io.File(audioFilePath);
            if (!audioFile.exists() || audioFile.length() == 0) {
                Toast.makeText(this, "Recording failed", Toast.LENGTH_SHORT).show();
                return;
            }
            // ✅ FIX: readFully guarantees ALL bytes are read — read() may return early
            byte[] audioBytes = new byte[(int) audioFile.length()];
            try (java.io.DataInputStream dis = new java.io.DataInputStream(
                    new java.io.FileInputStream(audioFile))) {
                dis.readFully(audioBytes);
            }

            String uploadPath = "chat_audio/" + conversationId + "/" + System.currentTimeMillis() + ".3gp";
            firebaseManager.uploadRawBytes(audioBytes, uploadPath, "audio/3gpp",
                    new JobLinkerFirebaseManager.UploadCallback() {
                        @Override public void onSuccess(String downloadUrl) {
                            audioFile.delete();
                            Message msg = new Message(conversationId, currentUserId, otherUserId,
                                    "🎤 Voice message (" + duration + ")");
                            msg.setMessageType("audio");
                            msg.setImageUrl(downloadUrl);
                            sendMessageObject(msg);
                        }
                        @Override public void onProgress(int progress) {}
                        @Override public void onFailure(String error) {
                            audioFile.delete();
                            Toast.makeText(ChatActivity.this,
                                    "Failed to send voice message", Toast.LENGTH_SHORT).show();
                        }
                    });
        } catch (Exception e) {
            Toast.makeText(this, "Could not send voice message: " + e.getMessage(),
                    Toast.LENGTH_SHORT).show();
        }
    }

    private void cancelRecording() {
        if (!isRecording) return;
        stopRecording();
        File f = new File(audioFilePath);
        if (f.exists()) f.delete();
        Toast.makeText(this, "Recording cancelled", Toast.LENGTH_SHORT).show();
    }

    private void stopRecording() {
        isRecording = false;
        recordingHandler.removeCallbacks(recordingTimerRunnable);
        layoutRecordingBar.setVisibility(View.GONE);
        if (viewRecordingDot != null) viewRecordingDot.setAlpha(1f);
        btnSend.setImageResource(R.drawable.ic_mic);
        try {
            if (mediaRecorder != null) {
                mediaRecorder.stop();
                mediaRecorder.release();
                mediaRecorder = null;
            }
        } catch (Exception e) {
            mediaRecorder = null;
        }
    }

    private void startRecordingDotAnimation() {
        Runnable blink = new Runnable() {
            @Override public void run() {
                if (!isRecording) return;
                viewRecordingDot.animate().alpha(0f).setDuration(500)
                        .withEndAction(() -> viewRecordingDot.animate().alpha(1f).setDuration(500)
                                .withEndAction(this).start()).start();
            }
        };
        blink.run();
    }

    // ══════════════════════════════════════════════
    // SEND MESSAGES
    // ══════════════════════════════════════════════
    private void sendTextMessage(String text) {
        Message message = new Message(conversationId, currentUserId, otherUserId, text);
        message.setMessageType("text");
        sendMessageObject(message);
        etMessage.setText("");
    }

    private void sendImageMessage(Uri imageUri) {
        byte[] bytes = readUriBytes(imageUri);
        if (bytes == null || bytes.length == 0) {
            Toast.makeText(this, "Could not read image", Toast.LENGTH_SHORT).show();
            return;
        }
        String uploadPath = "chat_images/" + conversationId + "/" + System.currentTimeMillis() + ".jpg";
        firebaseManager.uploadBytes(bytes, uploadPath,
                new JobLinkerFirebaseManager.UploadCallback() {
                    @Override public void onSuccess(String downloadUrl) {
                        Message msg = new Message(conversationId, currentUserId, otherUserId, "📷 Photo");
                        msg.setMessageType("image");
                        msg.setImageUrl(downloadUrl);
                        sendMessageObject(msg);
                    }
                    @Override public void onProgress(int p) {}
                    @Override public void onFailure(String error) {
                        Toast.makeText(ChatActivity.this,
                                "Failed to send image: " + error, Toast.LENGTH_SHORT).show();
                    }
                });
    }

    private byte[] readUriBytes(Uri uri) {
        try {
            java.io.InputStream is = getContentResolver().openInputStream(uri);
            if (is == null) return null;
            java.io.ByteArrayOutputStream buffer = new java.io.ByteArrayOutputStream();
            byte[] chunk = new byte[8192]; int read;
            while ((read = is.read(chunk)) != -1) buffer.write(chunk, 0, read);
            is.close();
            return buffer.toByteArray();
        } catch (Exception e) {
            Log.e("ChatActivity", "readUriBytes failed: " + e.getMessage());
            return null;
        }
    }

    private void sendDocumentMessage(Uri documentUri) {
        String fileName = "document";
        try {
            android.database.Cursor cursor = getContentResolver().query(
                    documentUri, null, null, null, null);
            if (cursor != null && cursor.moveToFirst()) {
                int idx = cursor.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME);
                if (idx >= 0) fileName = cursor.getString(idx);
                cursor.close();
            }
        } catch (Exception ignored) {}

        byte[] bytes = readUriBytes(documentUri);
        if (bytes == null || bytes.length == 0) {
            Toast.makeText(this, "Could not read document", Toast.LENGTH_SHORT).show();
            return;
        }

        final String finalName = fileName;
        String uploadPath = "chat_documents/" + conversationId + "/" + System.currentTimeMillis();
        firebaseManager.uploadBytes(bytes, uploadPath,
                new JobLinkerFirebaseManager.UploadCallback() {
                    @Override public void onSuccess(String downloadUrl) {
                        Message msg = new Message(conversationId, currentUserId, otherUserId,
                                "📄 " + finalName);
                        msg.setMessageType("document");
                        msg.setImageUrl(downloadUrl);
                        sendMessageObject(msg);
                    }
                    @Override public void onProgress(int p) {}
                    @Override public void onFailure(String error) {
                        Toast.makeText(ChatActivity.this,
                                "Failed to upload document", Toast.LENGTH_SHORT).show();
                    }
                });
    }

    private void sendMessageObject(Message message) {
        firebaseManager.sendMessage(message, new JobLinkerFirebaseManager.DataCallback<String>() {
            @Override public void onSuccess(String id) {
                message.setMessageId(id);
                messages.add(message);
                messageAdapter.notifyItemInserted(messages.size() - 1);
                recyclerMessages.scrollToPosition(messages.size() - 1);
            }
            @Override public void onFailure(String error) {
                Toast.makeText(ChatActivity.this,
                        "Failed to send: " + error, Toast.LENGTH_SHORT).show();
            }
        });
    }

    // ══════════════════════════════════════════════
    // REAL-TIME LISTENER
    // ══════════════════════════════════════════════
    private void setupMessageListener() {
        messageListener = firebaseManager.listenToMessages(conversationId,
                new JobLinkerFirebaseManager.ListCallback<Message>() {
                    @Override public void onSuccess(List<Message> list) {
                        messages.clear();
                        messages.addAll(list);
                        messageAdapter.notifyDataSetChanged();
                        if (!messages.isEmpty())
                            recyclerMessages.scrollToPosition(messages.size() - 1);
                        markMessagesAsRead();
                    }
                    @Override public void onFailure(String error) {
                        Toast.makeText(ChatActivity.this,
                                "Error loading messages: " + error, Toast.LENGTH_SHORT).show();
                    }
                });
    }

    private void loadUserStatus() {
        firebaseManager.getUser(otherUserId, new JobLinkerFirebaseManager.DataCallback<User>() {
            @Override public void onSuccess(User user) {
                if (user.isOnline()) {
                    tvStatus.setText(R.string.online);
                    tvStatus.setTextColor(getResources().getColor(R.color.success, null));
                } else {
                    tvStatus.setText(R.string.offline);
                    tvStatus.setTextColor(getResources().getColor(R.color.text_secondary, null));
                }
            }
            @Override public void onFailure(String error) {}
        });
    }

    private void markMessagesAsRead() {
        for (Message m : messages) {
            if (!m.isMessageRead() && currentUserId.equals(m.getMessageReceiverId())) {
                firebaseManager.markMessageAsRead(m.getMessageId(),
                        new JobLinkerFirebaseManager.VoidCallback() {
                            @Override public void onSuccess() {}
                            @Override public void onFailure(String e) {}
                        });
            }
        }
    }

    private void initiateCall(String callType) {
        Intent intent = new Intent(this, CallActivity.class);
        intent.putExtra(CallActivity.EXTRA_RECEIVER_ID,     otherUserId);
        intent.putExtra(CallActivity.EXTRA_RECEIVER_NAME,   otherUserName);
        intent.putExtra(CallActivity.EXTRA_RECEIVER_AVATAR, otherUserAvatar);
        intent.putExtra(CallActivity.EXTRA_CALL_TYPE,       callType);
        startActivity(intent);
    }

    // ══════════════════════════════════════════════
    // PERMISSIONS
    // ══════════════════════════════════════════════
    @Override
    public void onRequestPermissionsResult(int requestCode,
                                           @NonNull String[] permissions,
                                           @NonNull int[] grantResults) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);
        if (grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
            if (requestCode == REQUEST_RECORD_AUDIO) startVoiceRecording();
            else if (requestCode == REQUEST_CAMERA)  openCamera();
        } else {
            Toast.makeText(this,
                    requestCode == REQUEST_RECORD_AUDIO
                            ? "Microphone permission required for voice messages"
                            : "Camera permission required",
                    Toast.LENGTH_SHORT).show();
        }
    }

    // ══════════════════════════════════════════════
    // AUDIO PLAYBACK  (called by MessageAdapter)
    // ══════════════════════════════════════════════
    public void playVoiceMessage(String url, Runnable onStart, Runnable onStop) {
        // ✅ FIX #5: guard null URL before calling .equals()
        if (url == null || url.isEmpty()) {
            if (onStop != null) onStop.run();
            return;
        }

        // Toggle: tap same message while playing → stop
        if (url.equals(playingUrl) && audioPlayer != null) {
            stopAudioPlayer();
            if (onStop != null) onStop.run();
            return;
        }

        stopAudioPlayer();

        audioPlayer = new MediaPlayer();
        playingUrl  = url;
        final MediaPlayer player = audioPlayer; // local ref guards against race condition

        try {
            // ✅ FIX #3: AudioAttributes MUST be set before setDataSource
            audioPlayer.setAudioAttributes(
                    new android.media.AudioAttributes.Builder()
                            .setContentType(android.media.AudioAttributes.CONTENT_TYPE_SPEECH)
                            .setUsage(android.media.AudioAttributes.USAGE_MEDIA)
                            .build());

            audioPlayer.setDataSource(url);

            audioPlayer.setOnPreparedListener(mp -> {
                // ✅ FIX #4: stale-player guard — player may have been released already
                if (mp != player || audioPlayer != player) {
                    try { mp.release(); } catch (Exception ignored) {}
                    return;
                }
                // ✅ FIX #2: request audio focus — without this the OS silences playback
                if (!requestAudioFocus()) {
                    if (onStop != null) onStop.run();
                    stopAudioPlayer();
                    return;
                }
                if (onStart != null) onStart.run();
                mp.start();
            });

            audioPlayer.setOnCompletionListener(mp -> {
                abandonAudioFocus();
                if (onStop != null) onStop.run();
                stopAudioPlayer();
            });

            audioPlayer.setOnErrorListener((mp, what, extra) -> {
                Log.e("ChatActivity", "MediaPlayer error what=" + what + " extra=" + extra);
                Toast.makeText(this, "Cannot play audio", Toast.LENGTH_SHORT).show();
                abandonAudioFocus();
                if (onStop != null) onStop.run();
                stopAudioPlayer();
                return true;
            });

            audioPlayer.prepareAsync();

        } catch (Exception e) {
            Log.e("ChatActivity", "playVoiceMessage failed: " + e.getMessage(), e);
            Toast.makeText(this, "Cannot play audio: " + e.getMessage(), Toast.LENGTH_SHORT).show();
            if (onStop != null) onStop.run();
            stopAudioPlayer();
        }
    }

    private boolean requestAudioFocus() {
        if (audioManager == null)
            audioManager = (android.media.AudioManager) getSystemService(AUDIO_SERVICE);

        audioFocusRequest = new android.media.AudioFocusRequest.Builder(
                android.media.AudioManager.AUDIOFOCUS_GAIN_TRANSIENT)
                .setAudioAttributes(new android.media.AudioAttributes.Builder()
                        .setUsage(android.media.AudioAttributes.USAGE_MEDIA)
                        .setContentType(android.media.AudioAttributes.CONTENT_TYPE_SPEECH)
                        .build())
                .setOnAudioFocusChangeListener(focusChange -> {
                    if (focusChange == android.media.AudioManager.AUDIOFOCUS_LOSS ||
                            focusChange == android.media.AudioManager.AUDIOFOCUS_LOSS_TRANSIENT) {
                        runOnUiThread(this::stopAudioPlayer);
                    }
                })
                .build();

        return audioManager.requestAudioFocus(audioFocusRequest)
                == android.media.AudioManager.AUDIOFOCUS_REQUEST_GRANTED;
    }

    private void abandonAudioFocus() {
        if (audioManager != null && audioFocusRequest != null) {
            audioManager.abandonAudioFocusRequest(audioFocusRequest);
            audioFocusRequest = null;
        }
    }

    public void stopAudioPlayer() {
        // ✅ FIX #4: capture then null — prevents double-release on re-entrant calls
        MediaPlayer p = audioPlayer;
        audioPlayer   = null;
        playingUrl    = null;
        if (p != null) {
            try { p.stop();    } catch (Exception ignored) {}
            try { p.release(); } catch (Exception ignored) {}
        }
        abandonAudioFocus();
    }

    // ══════════════════════════════════════════════
    // LIFECYCLE
    // ══════════════════════════════════════════════
    @Override
    protected void onDestroy() {
        super.onDestroy();
        stopAudioPlayer();
        if (messageListener != null) messageListener.remove();
        if (isRecording) stopRecording();
        recordingHandler.removeCallbacksAndMessages(null);
    }
}

