        if (btnAbout != null) {
            btnAbout.setOnClickListener(v -> showTextDialog("About JobLinker",
                "JobLinker v1.0\n\n" +
                "JobLinker connects job seekers with employers through a modern, " +
                "easy-to-use mobile platform.\n\n" +
                "Features:\n" +
                "• Post and browse job listings\n" +
