                return new Locale("pl");
            case "turkish":
            case "tr":
                return new Locale("tr");
            case "english":
            case "en":
            default:
                return new Locale("en");
        }
    }

    /**
     * Get language code from full name
     */
    public static String getLanguageCode(String language) {
        switch (language.toLowerCase()) {
